/*!40014 SET @OLD_UNIQUE_CHECKS=@@UNIQUE_CHECKS, UNIQUE_CHECKS=0 */;
/*!40014 SET @OLD_FOREIGN_KEY_CHECKS=@@FOREIGN_KEY_CHECKS, FOREIGN_KEY_CHECKS=0 */;
/*!40101 SET @OLD_SQL_MODE=@@SQL_MODE, SQL_MODE='NO_AUTO_VALUE_ON_ZERO' */;
/*!40111 SET @OLD_SQL_NOTES=@@SQL_NOTES, SQL_NOTES=0 */;

INSERT IGNORE INTO `chapter` (`id`, `subject_id`, `parent_id`, `name`, `sort_order`, `created_at`, `updated_at`) VALUES (2,1,NULL,'第一章 物质世界及其发展规律',1,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(3,1,NULL,'第二章 认识世界和改造世界',2,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(4,1,NULL,'第三章 人类社会及其发展规律',3,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(5,2,NULL,'第一章 反对外国侵略的斗争',1,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(6,2,NULL,'第二章 对国家出路的早期探索',2,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(7,3,NULL,'第一章 新时代坚持和发展中国特色社会主义',1,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(8,4,NULL,'第一部分 阅读判断',1,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(9,4,NULL,'第二部分 阅读选择',2,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(12,4,NULL,'第三部分 概括段落大意和补全句子',0,'2026-10-16 07:45:20','2026-10-16 07:45:20'),(13,4,NULL,'第四部分 填句补文',0,'2026-10-16 07:45:20','2026-10-16 07:45:20'),(14,4,NULL,'第五部分 填词补文',0,'2026-10-16 07:45:21','2026-10-16 07:45:21'),(15,4,NULL,'第六部分 完形补文',0,'2026-10-16 07:45:22','2026-10-16 07:45:22'),(16,4,NULL,'第七部分 短文写作',0,'2026-10-16 07:45:22','2026-10-16 07:45:22');

INSERT IGNORE INTO `question` (`id`, `subject_id`, `chapter_id`, `type`, `stem`, `options`, `answer`, `answer_points`, `analysis`, `difficulty`, `source`, `source_year`, `score`, `status`, `ai_analysis`, `ai_analysis_at`, `created_at`, `updated_at`) VALUES (4,1,2,'SINGLE_CHOICE','马克思主义哲学的基本问题是（  ）','[{\"key\": \"A\", \"text\": \"物质和意识的关系问题\"}, {\"key\": \"B\", \"text\": \"思维和存在的关系问题\"}, {\"key\": \"C\", \"text\": \"世界的本原问题\"}, {\"key\": \"D\", \"text\": \"世界是否可知的问题\"}]','B',NULL,'恩格斯指出，全部哲学特别是近代哲学的重大的基本问题，是思维和存在的关系问题。',1,'演示数据 · 2024年10月真题',2024,2.0,'PUBLISHED',NULL,NULL,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(5,1,2,'MULTIPLE_CHOICE','下列选项中，属于客观唯心主义观点的有（  ）','[{\"key\": \"A\", \"text\": \"存在就是被感知\"}, {\"key\": \"B\", \"text\": \"理生万物，理主动静\"}, {\"key\": \"C\", \"text\": \"物质决定意识\"}, {\"key\": \"D\", \"text\": \"世界是绝对精神的产物\"}]','BD',NULL,'客观唯心主义把某种脱离人的“客观精神”当作世界本原。B、D 属于客观唯心主义，A 属于主观唯心主义，C 是唯物主义。',2,'演示数据 · 2024年10月真题',2024,2.0,'PUBLISHED',NULL,NULL,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(6,1,3,'SINGLE_CHOICE','实践是检验真理的唯一标准，这是因为实践具有（  ）','[{\"key\": \"A\", \"text\": \"直接现实性\"}, {\"key\": \"B\", \"text\": \"主观能动性\"}, {\"key\": \"C\", \"text\": \"社会历史性\"}, {\"key\": \"D\", \"text\": \"客观规律性\"}]','A',NULL,'实践的直接现实性，使它能把主观认识同客观实际联系起来加以对照。',2,'演示数据 · 2023年10月真题',2023,2.0,'PUBLISHED',NULL,NULL,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(7,2,5,'SINGLE_CHOICE','中国近代史上第一个不平等条约是（  ）','[{\"key\": \"A\", \"text\": \"《北京条约》\"}, {\"key\": \"B\", \"text\": \"《南京条约》\"}, {\"key\": \"C\", \"text\": \"《马关条约》\"}, {\"key\": \"D\", \"text\": \"《辛丑条约》\"}]','B',NULL,'1842年签订的中英《南京条约》是中国近代史上第一个不平等条约。',1,'演示数据 · 2024年4月真题',2024,2.0,'PUBLISHED',NULL,NULL,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(8,3,7,'SINGLE_CHOICE','中国特色社会主义最本质的特征是（  ）','[{\"key\": \"A\", \"text\": \"共同富裕\"}, {\"key\": \"B\", \"text\": \"中国共产党领导\"}, {\"key\": \"C\", \"text\": \"社会主义市场经济\"}, {\"key\": \"D\", \"text\": \"人民当家作主\"}]','B',NULL,'中国特色社会主义最本质的特征是中国共产党领导，这也是中国特色社会主义制度的最大优势。',1,'演示数据 · 2024年10月真题',2024,2.0,'PUBLISHED',NULL,NULL,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(10,1,4,'SHORT_ANSWER','简述生产力与生产关系的辩证关系。',NULL,NULL,'[\"生产力决定生产关系，生产力状况决定生产关系的性质和变化\", \"生产关系反作用于生产力，适合时促进发展，不适合时阻碍发展\", \"生产关系一定要适合生产力状况，这是社会发展的基本规律\"]',NULL,2,'演示数据 · 2024年10月真题',2024,6.0,'PUBLISHED',NULL,NULL,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(11,1,4,'ESSAY','试述社会存在与社会意识的辩证关系及其现实意义。',NULL,NULL,'[\"社会存在决定社会意识，社会意识是社会存在的反映\", \"社会意识具有相对独立性，有时落后于社会存在，有时超前于社会存在\", \"先进的社会意识对社会发展起积极的推动作用，落后的社会意识起阻碍作用\", \"现实意义：坚持物质文明和精神文明协调发展，重视意识形态工作\"]',NULL,3,'演示数据 · 2023年10月真题',2023,10.0,'PUBLISHED',NULL,NULL,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(12,1,NULL,'SHORT_ANSWER','简述矛盾的普遍性与特殊性的关系。',NULL,NULL,'[\"矛盾的普遍性即共性，特殊性即个性，二者相互联结\", \"普遍性寓于特殊性之中，并通过特殊性表现出来\", \"特殊性也离不开普遍性，二者在一定条件下相互转化\"]',NULL,2,'演示数据 · 未归章',2023,6.0,'PUBLISHED',NULL,NULL,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(13,1,NULL,'SHORT_ANSWER','（待校对）简述实践与认识的辩证关系。',NULL,NULL,'[\"实践是认识的基础，决定认识的产生和发展\", \"认识对实践具有反作用，正确的认识指导实践取得成功\"]',NULL,2,'演示数据 · 待校对',2024,6.0,'DRAFT',NULL,NULL,'2026-10-15 07:07:59','2026-10-15 07:07:59'),(14,1,2,'SINGLE_CHOICE','马克思主义最根本的世界观和方法论是(  )','[{\"key\": \"A\", \"text\": \"辩证唯物主义和历史唯物主义\"}, {\"key\": \"B\", \"text\": \"机械唯物主义和唯心主义\"}, {\"key\": \"C\", \"text\": \"朴素唯物主义和形而上学\"}, {\"key\": \"D\", \"text\": \"经验主义和理性主义\"}]','A',NULL,'马克思主义的全部理论都建立在辩证唯物主义与历史唯物主义之上。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(15,1,2,'SINGLE_CHOICE','哲学的基本问题是(  )','[{\"key\": \"A\", \"text\": \"思维和存在的关系问题\"}, {\"key\": \"B\", \"text\": \"物质和运动的关系问题\"}, {\"key\": \"C\", \"text\": \"认识和实践的关系问题\"}, {\"key\": \"D\", \"text\": \"主观和客观的关系问题\"}]','A',NULL,'恩格斯明确提出:全部哲学,特别是近代哲学的重大基本问题,是思维和存在的关系问题。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(16,1,2,'SINGLE_CHOICE','“世界不是既成事物的集合体,而是过程的集合体”,这一观点属于(  )','[{\"key\": \"A\", \"text\": \"唯物辩证法\"}, {\"key\": \"B\", \"text\": \"形而上学\"}, {\"key\": \"C\", \"text\": \"唯心主义\"}, {\"key\": \"D\", \"text\": \"不可知论\"}]','A',NULL,'把世界理解为过程,即用联系和发展的观点看世界,是唯物辩证法的基本特征。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(17,1,2,'SINGLE_CHOICE','物质的唯一特性是(  )','[{\"key\": \"A\", \"text\": \"客观实在性\"}, {\"key\": \"B\", \"text\": \"可知性\"}, {\"key\": \"C\", \"text\": \"运动\"}, {\"key\": \"D\", \"text\": \"矛盾性\"}]','A',NULL,'列宁指出,物质的唯一特性是客观实在性,它存在于人的意识之外并能为人所反映。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(18,1,2,'SINGLE_CHOICE','“动者恒动,静者恒静”这一说法(  )','[{\"key\": \"A\", \"text\": \"否认了运动和静止的辩证统一\"}, {\"key\": \"B\", \"text\": \"肯定了绝对运动\"}, {\"key\": \"C\", \"text\": \"说明了静止是有条件的\"}, {\"key\": \"D\", \"text\": \"体现了度量的思想\"}]','A',NULL,'把动静绝对割裂,否认静止中有运动、运动中有静止,是形而上学的不动论。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(19,1,2,'SINGLE_CHOICE','空间、时间是(  )','[{\"key\": \"A\", \"text\": \"物质运动的存在形式\"}, {\"key\": \"B\", \"text\": \"主观发明的协调系统\"}, {\"key\": \"C\", \"text\": \"物质运动的外部容器\"}, {\"key\": \"D\", \"text\": \"与物质运动无关的形式\"}]','A',NULL,'辩证唯物主义认为,时间和空间是运动着的物质的存在形式。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(20,1,2,'SINGLE_CHOICE','“机不遇工,不能成器”说明,在意识活动方面要重视(  )','[{\"key\": \"A\", \"text\": \"意识的能动作用\"}, {\"key\": \"B\", \"text\": \"物质的决定作用\"}, {\"key\": \"C\", \"text\": \"实践的客观形式\"}, {\"key\": \"D\", \"text\": \"规律的强制性\"}]','A',NULL,'强调意识的能动作用,但注意它必须以尊重客观规律为前提。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(21,1,2,'SINGLE_CHOICE','正确发挥意识能动作用的前提是(  )','[{\"key\": \"A\", \"text\": \"认识和遵循客观规律\"}, {\"key\": \"B\", \"text\": \"承认意识的决定作用\"}, {\"key\": \"C\", \"text\": \"摆脱具体条件的制约\"}, {\"key\": \"D\", \"text\": \"树立远大理想\"}]','A',NULL,'意识能动作用的发挥受制于客观规律和条件,遵循规律是前提。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(22,1,2,'SINGLE_CHOICE','唯物辩证法的两个总特征是(  )','[{\"key\": \"A\", \"text\": \"联系和发展\"}, {\"key\": \"B\", \"text\": \"对立和统一\"}, {\"key\": \"C\", \"text\": \"量变和质变\"}, {\"key\": \"D\", \"text\": \"肯定和否定\"}]','A',NULL,'普遍联系和永恒发展是唯物辩证法的两大总特征。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(23,1,2,'SINGLE_CHOICE','“沉舟侧畔千帆过,病树前头万木春”蕴含的哲理是(  )','[{\"key\": \"A\", \"text\": \"新事物必然战胜旧事物\"}, {\"key\": \"B\", \"text\": \"量变必然引起质变\"}, {\"key\": \"C\", \"text\": \"事物是静止不变的\"}, {\"key\": \"D\", \"text\": \"发展的道路是一帆风顺的\"}]','A',NULL,'以新喻取代旧,说明发展的前进性,新事物是不可战胜的。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(24,1,2,'SINGLE_CHOICE','事物的质和量的统一是(  )','[{\"key\": \"A\", \"text\": \"度\"}, {\"key\": \"B\", \"text\": \"关节点\"}, {\"key\": \"C\", \"text\": \"区间\"}, {\"key\": \"D\", \"text\": \"规模\"}]','A',NULL,'度是保持事物质的稳定性的数量界限,即事物的限度、幅度和范围。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(25,1,2,'SINGLE_CHOICE','认识事物的根本方法是(  )','[{\"key\": \"A\", \"text\": \"矛盾分析法\"}, {\"key\": \"B\", \"text\": \"阶级分析法\"}, {\"key\": \"C\", \"text\": \"逻辑分析法\"}, {\"key\": \"D\", \"text\": \"系统分析法\"}]','A',NULL,'矛盾分析法是对立统一规律方法论的根本要求,是认识事物的根本方法。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(26,1,2,'SINGLE_CHOICE','“和实生物,同则不继”说明矛盾的同一性以(  )为前提','[{\"key\": \"A\", \"text\": \"差别和对立\"}, {\"key\": \"B\", \"text\": \"绝对一致\"}, {\"key\": \"C\", \"text\": \"外部和谐\"}, {\"key\": \"D\", \"text\": \"量的均衡\"}]','A',NULL,'同一是对立中的同一,没有差别就没有“和”,就没有万物的生长。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(27,1,3,'SINGLE_CHOICE','感性认识和理性认识统一的基础是(  )','[{\"key\": \"A\", \"text\": \"实践\"}, {\"key\": \"B\", \"text\": \"感觉\"}, {\"key\": \"C\", \"text\": \"逻辑\"}, {\"key\": \"D\", \"text\": \"经验\"}]','A',NULL,'二者都是在实践中产生、又在实践中统一起来的。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(28,1,3,'SINGLE_CHOICE','“纸上得来终觉浅,绝知此事要躬行”,强调认识发展的必要环节是(  )','[{\"key\": \"A\", \"text\": \"回到实践中去\"}, {\"key\": \"B\", \"text\": \"丰富感性材料\"}, {\"key\": \"C\", \"text\": \"进行抽象思维\"}, {\"key\": \"D\", \"text\": \"学习书本知识\"}]','A',NULL,'从书本得来的认识仍属间接经验,必须回到实践中深化、检验。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(29,1,3,'SINGLE_CHOICE','检验认识真理性的唯一标准是(  )','[{\"key\": \"A\", \"text\": \"实践\"}, {\"key\": \"B\", \"text\": \"逻辑证明\"}, {\"key\": \"C\", \"text\": \"权威判定\"}, {\"key\": \"D\", \"text\": \"多数人意见\"}]','A',NULL,'实践是检验真理的唯一标准,这是由真理的本性和实践的特点决定的。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(30,1,3,'SINGLE_CHOICE','“真理再多走一小步,哪怕是朝同一方向,就会变成谬误”,说明(  )','[{\"key\": \"A\", \"text\": \"真理是具体的有条件的\"}, {\"key\": \"B\", \"text\": \"真理和谬误没有界限\"}, {\"key\": \"C\", \"text\": \"真理是主观随意的\"}, {\"key\": \"D\", \"text\": \"谬误必然转化为真理\"}]','A',NULL,'任何真理都有适用的条件和范围,超出就变成谬误。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(31,1,3,'SINGLE_CHOICE','马克思主义真理观认为,真理的客观性是指(  )','[{\"key\": \"A\", \"text\": \"真理的内容客观、检验标准客观\"}, {\"key\": \"B\", \"text\": \"真理的形式是客观的\"}, {\"key\": \"C\", \"text\": \"真理对任何人都是公平的\"}, {\"key\": \"D\", \"text\": \"真理没有阶级性\"}]','A',NULL,'真理的客观性指其内容是对客观事物的正确反映,检验标准(实践)也是客观的。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(32,1,3,'SINGLE_CHOICE','价值评价的特点是(  )','[{\"key\": \"A\", \"text\": \"以主客体的价值关系为认识对象\"}, {\"key\": \"B\", \"text\": \"评价结果与评价主体无关\"}, {\"key\": \"C\", \"text\": \"评价没有客观标准\"}, {\"key\": \"D\", \"text\": \"评价是纯主观随意的\"}]','A',NULL,'价值评价是关于客体对主体意义的判断,以价值关系为对象,受主体影响但有客观标准。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(33,1,4,'SINGLE_CHOICE','“人类发展史是一个自然历史过程”,这一论断的根据是(  )','[{\"key\": \"A\", \"text\": \"社会发展具有客观规律性\"}, {\"key\": \"B\", \"text\": \"人的活动是有意识的\"}, {\"key\": \"C\", \"text\": \"社会生活本质上是实践的\"}, {\"key\": \"D\", \"text\": \"生产方式是社会存在\"}]','A',NULL,'马克思意在说明社会发展同自然界一样有其不以人的意志为转移的客观规律。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(34,1,4,'SINGLE_CHOICE','在社会发展中起决定作用的因素是(  )','[{\"key\": \"A\", \"text\": \"物质资料的生产方式\"}, {\"key\": \"B\", \"text\": \"地理环境和人口因素\"}, {\"key\": \"C\", \"text\": \"社会心理\"}, {\"key\": \"D\", \"text\": \"英雄人物\"}]','A',NULL,'生产方式是社会发展的决定力量,它决定社会的性质和面貌并决定其变革。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(35,1,4,'SINGLE_CHOICE','“民为邦本,本固邦宁”与唯物史观相通之处在于它承认(  )','[{\"key\": \"A\", \"text\": \"人民群众是历史的创造者\"}, {\"key\": \"B\", \"text\": \"英雄创造历史\"}, {\"key\": \"C\", \"text\": \"偶然性支配历史\"}, {\"key\": \"D\", \"text\": \"帝王将相决定社会发展\"}]','A',NULL,'朴素民本思想承认民众的地位,与唯物史观群众史观有相通之处。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(36,1,4,'SINGLE_CHOICE','社会存在与社会意识的关系问题是(  )','[{\"key\": \"A\", \"text\": \"社会历史观的基本问题\"}, {\"key\": \"B\", \"text\": \"哲学的基本问题\"}, {\"key\": \"C\", \"text\": \"认识论的基本问题\"}, {\"key\": \"D\", \"text\": \"伦理学的基本问题\"}]','A',NULL,'对社会存在与社会意识何者为第一性的不同回答,划分了唯物史观与唯心史观。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(37,1,4,'SINGLE_CHOICE','人的本质在于(  )','[{\"key\": \"A\", \"text\": \"一切社会关系的总和\"}, {\"key\": \"B\", \"text\": \"自然属性\"}, {\"key\": \"C\", \"text\": \"理性\"}, {\"key\": \"D\", \"text\": \"趋利避害的本能\"}]','A',NULL,'马克思指出,人的本质不是单个人所固有的抽象物,在其现实性上是一切社会关系的总和。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(38,1,4,'SINGLE_CHOICE','人生价值评价的根本尺度是(  )','[{\"key\": \"A\", \"text\": \"一个人的人生活动是否符合社会发展的客观规律\"}, {\"key\": \"B\", \"text\": \"能力大小\"}, {\"key\": \"C\", \"text\": \"动机纯正与否\"}, {\"key\": \"D\", \"text\": \"自我评价高低\"}]','A',NULL,'看一个人对社会和人民的贡献及其活动是否符合社会发展的客观规律。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(39,1,NULL,'SINGLE_CHOICE','资本主义经济危机的本质特征是(  )','[{\"key\": \"A\", \"text\": \"生产相对过剩\"}, {\"key\": \"B\", \"text\": \"需求绝对不足\"}, {\"key\": \"C\", \"text\": \"货币发行过多\"}, {\"key\": \"D\", \"text\": \"对外贸易逆差\"}]','A',NULL,'资本主义经济危机是相对过剩的危机,相对于劳动人民有支付能力的需求而言过剩。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(40,1,NULL,'SINGLE_CHOICE','马克思揭示资本主义工资本质的理论依据是(  )','[{\"key\": \"A\", \"text\": \"劳动力成为商品\"}, {\"key\": \"B\", \"text\": \"剩余价值分配\"}, {\"key\": \"C\", \"text\": \"平均利润形成\"}, {\"key\": \"D\", \"text\": \"地租资本化\"}]','A',NULL,'工人出卖的是劳动力而非劳动,工资是劳动力价值或价格的转化形式,掩盖了剩余价值的占有。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(41,1,NULL,'SINGLE_CHOICE','商品经济的基本矛盾是(  )','[{\"key\": \"A\", \"text\": \"私人劳动和社会劳动的矛盾\"}, {\"key\": \"B\", \"text\": \"使用价值和价值的矛盾\"}, {\"key\": \"C\", \"text\": \"具体劳动和抽象劳动的矛盾\"}, {\"key\": \"D\", \"text\": \"买卖脱节的矛盾\"}]','A',NULL,'在私有制商品经济中,私人劳动与社会劳动的矛盾是基本矛盾,它决定其他一切矛盾。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(42,1,NULL,'SINGLE_CHOICE','垄断价格的制定不能完全脱离价值,因为(  )','[{\"key\": \"A\", \"text\": \"价值规律仍然发挥作用\"}, {\"key\": \"B\", \"text\": \"垄断消除了竞争\"}, {\"key\": \"C\", \"text\": \"国家限制了价格\"}, {\"key\": \"D\", \"text\": \"成本决定一切\"}]','A',NULL,'垄断不能取消价值规律,垄断价格总额与价值总额仍然一致。',1,'2025年4月自测试卷(示例导入)',2025,1.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(43,1,4,'MULTIPLE_CHOICE','马克思主义产生的阶级和实践基础包括(   )','[{\"key\": \"A\", \"text\": \"无产阶级作为独立的政治力量登上历史舞台\"}, {\"key\": \"B\", \"text\": \"资本主义经济的发展\"}, {\"key\": \"C\", \"text\": \"工人运动的兴起\"}, {\"key\": \"D\", \"text\": \"科学技术的进步\"}]','ABC',NULL,'资本主义经济的发展和无产阶级壮大及其斗争实践,是马克思主义产生的经济社会根源与实践基础。',2,'2025年4月自测试卷(示例导入)',2025,2.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(44,1,2,'MULTIPLE_CHOICE','属于唯物辩证法基本范畴的有(   )','[{\"key\": \"A\", \"text\": \"原因和结果\"}, {\"key\": \"B\", \"text\": \"必然性和偶然性\"}, {\"key\": \"C\", \"text\": \"可能性和现实性\"}, {\"key\": \"D\", \"text\": \"内容和形式\"}]','ABCD',NULL,'四对范畴与本质和现象等共同构成辩证法的基本范畴体系。',2,'2025年4月自测试卷(示例导入)',2025,2.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(45,1,3,'MULTIPLE_CHOICE','实践的基本特征包括(   )','[{\"key\": \"A\", \"text\": \"客观实在性\"}, {\"key\": \"B\", \"text\": \"自觉能动性\"}, {\"key\": \"C\", \"text\": \"社会历史性\"}, {\"key\": \"D\", \"text\": \"直接现实性\"}]','ABCD',NULL,'实践是客观的物质活动,是有目的有意识的活动,是社会的历史的活动,并能把认识变为现实。',2,'2025年4月自测试卷(示例导入)',2025,2.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(46,1,3,'SHORT_ANSWER','简述感性认识与理性认识的辩证关系。',NULL,NULL,'[\"感性认识是认识的初级阶段,以感觉、知觉、表象为形式;理性认识是高级阶段,以概念、判断、推理为形式\", \"理性认识依赖于感性认识,感性认识有待于发展为理性认识,二者相互渗透\", \"二者统一的基础是实践;割裂两者会导致经验主义或教条主义\"]','认识论高频简答题,采分点为两阶段、相互依赖与渗透、实践基础。',2,'2025年4月自测试卷(示例导入)',2025,6.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(47,1,2,'SHORT_ANSWER','简述量变与质变的辩证关系及其方法论意义。',NULL,NULL,'[\"量变是事物数量的增减和场所的变更,质变是事物根本性质的变化\", \"量变是质变的必要准备,质变是量变的必然结果;质变又引起新的量变,二者相互交替\", \"方法论:既要脚踏实地注重积累,又要抓住时机促成飞跃,反对“激变论”和“庸俗进化论”\"]','发展的状态问题。方法论一定要答到“积累”与“抓住时机”两端。',2,'2025年4月自测试卷(示例导入)',2025,6.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(48,1,4,'SHORT_ANSWER','简述社会存在与社会意识的辩证关系。',NULL,NULL,'[\"社会存在决定社会意识:社会意识是社会存在的反映,并随社会存在的变化而变化\", \"社会意识具有相对独立性:它与社会存在发展不完全同步,有自身历史继承性,并能动地反作用于社会存在\", \"先进的社会意识促进社会发展,落后的社会意识阻碍社会发展\"]','历史观基本问题。相对独立性三点中答出任意两点即可得相应分数。',2,'2025年4月自测试卷(示例导入)',2025,6.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(49,1,3,'SHORT_ANSWER','简述真理与谬误的辩证关系。',NULL,NULL,'[\"二者界限确定:在同一对象、同一条件下,真理与谬误的对立是绝对的,不能混淆\", \"二者相互依存并在一定条件下转化:超出真理的适用条件和范围,真理就变为谬误\", \"同错误作斗争是真理发展的条件,真理在对谬误的批判中发展\"]','注意“确定界限”与“条件转化”两端,漏一面是典型失分点。',2,'2025年4月自测试卷(示例导入)',2025,6.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(50,1,4,'SHORT_ANSWER','为什么说人民群众是历史的创造者?',NULL,NULL,'[\"人民群众是物质财富的创造者,是社会存在和发展的基础\", \"人民群众是精神财富的创造者,其生活与实践是精神财富的源泉\", \"人民群众是社会变革的决定力量,推动社会形态更替\", \"群众创造活动受既定历史条件制约,需坚持群众观点和群众路线\"]','唯物史观核心结论。前三点为“创造者”的三维度,第四点是条件制约。',2,'2025年4月自测试卷(示例导入)',2025,6.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(51,1,2,'ESSAY','试述矛盾的普遍性和特殊性的辩证关系原理,并说明其对中国式现代化的指导意义。',NULL,NULL,'[\"普遍性即共性,指矛盾存在于一切事物发展过程中并贯穿每一过程始终\", \"特殊性即个性,指不同事物、同一事物不同阶段的矛盾各有其特点\", \"二者相互联结:普遍性寓于特殊性之中并通过特殊性表现出来,特殊性离不开普遍性;并在一定条件下相互转化\", \"这一关系是关于事物矛盾问题的精髓,是马克思主义普遍真理同各国具体实际相结合的哲学基础\", \"指导意义:中国式现代化既遵循各国现代化共同的普遍规律,又立足中国国情呈现自身特色,是共性与个性的统一\"]','马原传统大题模板:原理(普遍性—特殊性—关系—地位)+ 现实运用。',3,'2025年4月自测试卷(示例导入)',2025,10.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(52,1,4,'ESSAY','运用社会存在与社会意识关系的原理,分析文化自信的哲学依据。',NULL,NULL,'[\"社会存在决定社会意识,社会意识是对社会存在的反映\", \"中华优秀文化传统与当代中国式现代化的实践,是文化自信深厚的现实依据\", \"社会意识具有相对独立性,先进的社会意识对社会发展起积极推动作用\", \"文化自信作为先进的社会意识,能为民族复兴提供精神力量与价值支撑\", \"反对历史虚无主义,坚持马克思主义在意识形态领域的指导地位\"]','把文化看作社会意识的一种形式,从“根源于社会存在”和“能动反作用”两个方向展开。',3,'2025年4月自测试卷(示例导入)',2025,10.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:48:23','2026-10-15 22:48:23'),(55,1,2,'SINGLE_CHOICE','世界物质统一性原理是马克思主义哲学的基石,世界的真正统一性在于它的(  )','[{\"key\": \"A\", \"text\": \"普遍性\"}, {\"key\": \"B\", \"text\": \"物质性\"}, {\"key\": \"C\", \"text\": \"矛盾性\"}, {\"key\": \"D\", \"text\": \"运动性\"}]','B',NULL,'恩格斯指出,世界的统一性在于它的物质性。',1,'03709',NULL,2.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:54:22','2026-10-15 22:54:22'),(56,1,NULL,'SHORT_ANSWER','简述上层建筑对经济基础的反作用。',NULL,NULL,'[\"适合时促进巩固\", \"不适合时阻碍发展\", \"反作用性质取决于服务方向\"]',NULL,2,'03709',NULL,6.0,'PUBLISHED',NULL,NULL,'2026-10-15 22:54:22','2026-10-15 22:54:22'),(159,4,8,'READING_JUDGE','【原文 · Australia】\nAustralia was a country I always wanted to visit. This year I saved up some money and booked a flight to go travelling. I had some friends studying there, so it was a perfect opportunity to see friends and travel around.\n\nThe flight made me realize exactly how far away Australia is from home. I spent 10 hours flying from London to Hong Kong, then a further 8 hours to Sydney, my first stop in Australia. The flight went quite quickly though, since there were lots of films to keep me entertained.\n\nWhen I arrived, I felt strange. Everything was upside down over there. It was the start of winter in May! Fortunately, for me the weather was still warm and sunny. It also took me a while to get used to the time difference.\n\nAustralia is truly beautiful. It is full of views and wildlife you would not find anywhere else in the world. One of the highlights of my trip was visiting a koala (考拉) reserve in Brisbane. There were koalas everywhere sleeping in the trees. I even got a chance to hold one. I learnt lots of facts about koalas too. They can sleep for up to 22 hours a day to save energy! At the reserve there was also a big lawn full of kangaroos (袋鼠). We were allowed to feed and touch them. They were really cute and friendly.\n\nI loved visiting Australia, from the mountains and waterfalls in the National Parks to the long white sandy beaches. It\'s an incredible country and worth visiting. I\'m already dreaming of going back!\n\nI longed for a visit to Australia.','[{\"key\": \"T\", \"text\": \"True\"}, {\"key\": \"F\", \"text\": \"False\"}, {\"key\": \"NG\", \"text\": \"Not Given\"}]','T',NULL,'开头就说澳大利亚是他一直想去的国家。',1,'2026年4月英语(专升本)真题',2026,1.0,'DRAFT',NULL,NULL,'2026-10-16 07:54:55','2026-10-16 07:54:55'),(160,4,8,'READING_JUDGE','【原文 · Australia】\nAustralia was a country I always wanted to visit. This year I saved up some money and booked a flight to go travelling. I had some friends studying there, so it was a perfect opportunity to see friends and travel around.\n\nThe flight made me realize exactly how far away Australia is from home. I spent 10 hours flying from London to Hong Kong, then a further 8 hours to Sydney, my first stop in Australia. The flight went quite quickly though, since there were lots of films to keep me entertained.\n\nWhen I arrived, I felt strange. Everything was upside down over there. It was the start of winter in May! Fortunately, for me the weather was still warm and sunny. It also took me a while to get used to the time difference.\n\nAustralia is truly b