INSERT IGNORE INTO `import_log` (`id`, `source`, `subject_code`, `paper_name`, `status`, `total`, `imported`, `skipped`, `duplicated`, `issues`, `warnings`, `created_at`) VALUES (5,'PDF','13000','英语二1','PARTIAL',203,138,65,52,'[{\"stem\": \"【原文 · Organic Farming】Besides, organic farming cannot produce enough food for the world\'s population to survive. This could lead to starvation in countries that can produce enough food today.\\n\\n15. The problem of organic farming is _______ .\", \"index\": 117, \"reason\": \"options: 阅读选择是客观题,options 不能为空\"}, {\"stem\": \"【原文 · Insomnia (失眠)】\\nI just could not fall asleep the other night. I just didn\'t feel sleepy. I can\'t explain why, but it was really annoying.\\n\\nI got very bored lying in bed, so I decided to read a book. __(26)__ But even when I finished reading, I still didn\'t feel tired. So I listened to some peaceful music. That didn\'t work, either. I have heard people say if you have a warm drink before bedtime it will help you drift off to sleep. So I went downstairs and made myself a cup of tea. __(27)__ Still, I couldn\'t sleep. I was getting very frustrated by this point!\\n\\nIt felt strange to be awake while everyone else was asleep. __(28)__ In fact, it was a little bit frightening. When you go to sleep, it feels like one day ends and another begins. But if you stay up late, you realize that day and night are just a gentle transition (转变), a cycle which has no end and no beginning. At 4 a.m., I noticed a faint light coming through my curtains. The sun had started to rise!\", \"index\": 128, \"reason\": \"options: 填句补文是客观题,options 不能为空\"}, {\"stem\": \"【原文 · Insomnia (失眠)】\\nI just could not fall asleep the other night. I just didn\'t feel sleepy. I can\'t explain why, but it was really annoying.\\n\\nI got very bored lying in bed, so I decided to read a book. __(26)__ But even when I finished reading, I still didn\'t feel tired. So I listened to some peaceful music. That didn\'t work, either. I have heard people say if you have a warm drink before bedtime it will help you drift off to sleep. So I went downstairs and made myself a cup of tea. __(27)__ Still, I couldn\'t sleep. I was getting very frustrated by this point!\\n\\nIt felt strange to be awake while everyone else was asleep. __(28)__ In fact, it was a little bit frightening. When you go to sleep, it feels like one day ends and another begins. But if you stay up late, you realize that day and night are just a gentle transition (转变), a cycle which has no end and no beginning. At 4 a.m., I noticed a faint light coming through my curtains. The sun had started to rise!\", \"index\": 129, \"reason\": \"options: 填句补文是客观题,options 不能为空\"}, {\"stem\": \"【原文 · Insomnia (失眠)】\\nI just could not fall asleep the other night. I just didn\'t feel sleepy. I can\'t explain why, but it was really annoying.\\n\\nI got very bored lying in bed, so I decided to read a book. __(26)__ But even when I finished reading, I still didn\'t feel tired. So I listened to some peaceful music. That didn\'t work, either. I have heard people say if you have a warm drink before bedtime it will help you drift off to sleep. So I went downstairs and made myself a cup of tea. __(27)__ Still, I couldn\'t sleep. I was getting very frustrated by this point!\\n\\nIt felt strange to be awake while everyone else was asleep. __(28)__ In fact, it was a little bit frightening. When you go to sleep, it feels like one day ends and another begins. But if you stay up late, you realize that day and night are just a gentle transition (转变), a cycle which has no end and no beginning. At 4 a.m., I noticed a faint light coming through my curtains. The sun had started to rise!\", \"index\": 130, \"reason\": \"options: 填句补文是客观题,options 不能为空\"}, {\"stem\": \"【原文 · Smiles】\\nA smile costs nothing, but creates much. It enriches those who __(31)__, without making those who give poor. It happens in a __32__ and the memory of it sometimes lasts __33__. None are so rich that they can get along without it, and none so __34__ but are richer for its benefits. It creates __35__ in the home, and fosters goodwill in a business. It is rest to the weary (疲劳的), daylight to the __36__ and sunshine to the sad. Yet it cannot be bought, begged, borrowed, or stolen, for it is something that is no earthly good to anybody till it is given __37__. And if in the last-minute rush of Christmas __38__, some of our salespeople should be too __39__ to give you a smile, may we __40__ you to leave one of yours? For nobody needs a smile so much as those who have none left to give!\", \"index\": 133, \"reason\": \"options: 填词补文是客观题,options 不能为空\"}, {\"stem\": \"【原文 · Smiles】\\nA smile costs nothing, but creates much. It enriches those who __31__, without making those who give poor. It happens in a __(32)__ and the memory of it sometimes lasts __33__. None are so rich that they can get along without it, and none so __34__ but are richer for its benefits. It creates __35__ in the home, and fosters goodwill in a business. It is rest to the weary (疲劳的), daylight to the __36__ and sunshine to the sad. Yet it cannot be bought, begged, borrowed, or stolen, for it is something that is no earthly good to anybody till it is given __37__. And if in the last-minute rush of Christmas __38__, some of our salespeople should be too __39__ to give you a smile, may we __40__ you to leave one of yours? For nobody needs a smile so much as those who have none left to give!\", \"index\": 134, \"reason\": \"options: 填词补文是客观题,options 不能为空\"}, {\"stem\": \"【原文 · Smiles】\\nA smile costs nothing, but creates much. It enriches those who __31__, without making those who give poor. It happens in a __32__ and the memory of it sometimes lasts __(33)__. None are so rich that they can get along without it, and none so __34__ but are richer for its benefits. It creates __35__ in the home, and fosters goodwill in a business. It is rest to the weary (疲劳的), daylight to the __36__ and sunshine to the s